function Converter() {
  const [temperature, setTemperature] = useState({ text: '', scale: 'c' });
  const celsius = temperature.scale === 'c' ? temperature.text : toCelsius(temperature.text);
  const fahrenheit = temperature.scale === 'f' ? temperature.text : toFahrenheit(temperature.text);

  return <>
    <TemperatureInput value={celsius} onChange={text => setTemperature({ text, scale: 'c' })} />
    <TemperatureInput value={fahrenheit} onChange={text => setTemperature({ text, scale: 'f' })} />
  </>;
}
